<?php
namespace App\Services;
use Illuminate\Http\UploadedFile;
final class PackageService { public function inspect(UploadedFile $file):array { if(!class_exists(\ZipArchive::class))throw new \RuntimeException('ZIP support is unavailable.');$zip=new \ZipArchive();if($zip->open($file->getRealPath(),\ZipArchive::CHECKCONS)!==true)throw new \InvalidArgumentException('Package is not a valid ZIP archive.');$total=0;if($zip->numFiles<1||$zip->numFiles>100000){$zip->close();throw new \InvalidArgumentException('ZIP entry count is outside the allowed range.');}for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$name=str_replace('\\','/',$stat['name']);if(str_starts_with($name,'/')||preg_match('~(^|/)\.\.(/|$)~',$name)){$zip->close();throw new \InvalidArgumentException('ZIP contains an unsafe path.');}$total+=(int)$stat['size'];if($total>5*1024*1024*1024){$zip->close();throw new \InvalidArgumentException('Uncompressed package exceeds 5 GiB.');}}$zip->close();return ['sha256'=>hash_file('sha256',$file->getRealPath()),'size'=>$file->getSize()];} }
